function escapePythonString(value) {
  let escaped = "";

  for (const character of value) {
    if (character === "\\") {
      escaped += "\\\\";
      continue;
    }

    if (character === "'") {
      escaped += "\\'";
      continue;
    }

    if (character === "\n") {
      escaped += "\\n";
      continue;
    }

    if (character === "\r") {
      escaped += "\\r";
      continue;
    }

    if (character === "\t") {
      escaped += "\\t";
      continue;
    }

    escaped += character;
  }

  return `'${escaped}'`;
}

export function toPythonRepr(value) {
  if (value === null) {
    return "None";
  }

  if (typeof value === "string") {
    return escapePythonString(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonRepr(item)).join(", ")}]`;
